def check_n_3():
    # Target sums: {1, 2, 3}
    # Candidate a_i: {0, 1, 2}
    a = [0, 1, 2]
    n = len(a)
    sums = set()
    for i in range(n):
        for j in range(i + 1, n):
            sums.add(a[i] + a[j])

    required_sums = set(range(1, n * (n - 1) // 2 + 1))

    print(f"N=3 sums found: {sums}")
    print(f"Required sums: {required_sums}")

    return required_sums.issubset(sums)

